class GenericRunnerBase(GenericRunnerAsirEx, object):
    TEMP_ALLOWED_ALARMS = []

    def __init__(self, operation_description, bts_id=0, du_id=0, additional_allowed_alarms=None,
                 temp_allowed_alarms=None, critical_alarms=None, temp_critical_alarms=None, enable_listener=True,
                 add_default_faults=True, bts_type="GNB", **kwargs):
        self.bbu = convert_to_robot_kw(GnbDuOperations) if bts_type == "GNB" else convert_to_robot_kw(EnbDuOperations)
        self.com = convert_to_robot_kw(GnbCommissioning) if bts_type == "GNB" else convert_to_robot_kw(EnbCommissioning)
        self.cell = convert_to_robot_kw(GnbCellOperations) if bts_type == "GNB" else convert_to_robot_kw(
            EnbCellOperations)
        self.log = convert_to_robot_kw(GnbBtslogCollector) if bts_type == "GNB" else convert_to_robot_kw(
            EnbBtslogCollector)
        self.gnb_ru_lmi = convert_to_robot_kw(GnbRuSerialLogsCollector) if bts_type == "GNB" else convert_to_robot_kw(
            EnbRuSerialLogsCollector)
        self.ru = convert_to_robot_kw(GnbRuOperations) if bts_type == "GNB" else convert_to_robot_kw(EnbRuOperations)
        self.asir = None
        if convert_to_robot_kw(self.com.is_asir_configuration, bts_id=bts_id, du_id=du_id):
            self.asir = convert_to_robot_kw(GnbAsirHubOperations, parallel_warning=True, bts_id=bts_id) \
                if bts_type == "GNB" else convert_to_robot_kw(EnbAsirHubOperations, parallel_warning=True,
                                                              bts_id=bts_id)
        self.alarm = convert_to_robot_kw(GnbAlarmVerification)
        self.watchdog = convert_to_robot_kw(alarms_watchdog)
        self.operation_description = operation_description
        self.temp_allowed_alarms = copy(temp_allowed_alarms) if temp_allowed_alarms else []
        self.critical_alarms = critical_alarms if critical_alarms else []
        self.temp_critical_alarms = temp_critical_alarms if temp_critical_alarms else []
        self.additional_allowed_alarms = additional_allowed_alarms if additional_allowed_alarms else []
        self.du_id = du_id
        self.bts_id = bts_id
        self.bts_type = bts_type
        self._add_default_faults = add_default_faults
        self.delay_for_checking_onAir = 0
        self.delay_for_checking_allowed_alarms = 0
        self.delete_watchdog_alarms = True
        self.required_space = 10000
        self.collect_passed_snapshot = True
        self.perform_ru_power_reset_after_fail = False
        self.verify_params = True
        self.alarm_watchdog_restart = 21
        self.ru_device_regex = [r"{}{}_DU{}_RU\d+".format(self.bts_type, self.bts_id, self.du_id)]
        self.collect_ru_logs = True
        self.graceful_shutdown = False
        self._recover_reset_amount = 3
        self._cells_number = None
        self._iteration_start_time = None
        self._iteration_number = None
        self._iteration_status = {}
        self._current_status = None
        self._any_iteration_failed = False
        self._first_passed_iteration = None
        self._target = None
        self._iteration_log_path = None
        self._robot_log_path = convert_to_robot_kw(self.get_logs_path)
        self._watchdog_logs_dir = os.path.join(self._robot_log_path, "{}_Alarm_watchdog_logs".
                                               format(ws_du.format(self.bts_type, self.bts_id, self.du_id)))
        self._rfc_cells = []
        for arg in kwargs:
            setattr(self, str(arg), kwargs[arg])
        if self._add_default_faults:
            self.temp_allowed_alarms.extend(self.TEMP_ALLOWED_ALARMS)
        if enable_listener is True:
            convert_to_robot_kw(self.set_robot_listener)

    def run_in_loop(self, iterations=1, timeout=480, start_iteration=1):
        """
        Run operation in loop.

        :param iterations:          number of iterations
        :param start_iteration:     use to specify log directory
        :param timeout:             timeout for 'wait_for_all_cells_onair' after reset
        """
        try:
            timeout = convert_to_robot_kw(time_to_seconds, time=timeout)
            convert_to_robot_kw(self.actions_before_loop)
            convert_to_robot_kw(log_info_to_console, msg="Run {} iterations of {}".format(iterations,
                                                                                          self.operation_description))
            with RobotWrapper(wrap_name="{} FOR LOOP, ITERATIONS: {}".format(self.operation_description, iterations),
                              wrap_type="for") as wrapper:
                for iteration in range(int(start_iteration), int(iterations) + 1):
                    wrapper.create_level("{} iteration {}".format(self.operation_description, iteration),
                                         wrap_type="foritem", level=2)
                    convert_to_robot_kw(log_info_to_console, msg='Iteration: {}/{}'.format(iteration, iterations))
                    try:
                        convert_to_robot_kw(self.run_preconditions, iteration=iteration)
                        convert_to_robot_kw(self.checks_before_operation)
                        convert_to_robot_kw(self.actions_before_operation)
                        convert_to_robot_kw(self.run_operation)
                        convert_to_robot_kw(self.actions_after_operation)
                        convert_to_robot_kw(self._delay_for_checking)
                        convert_to_robot_kw(self.checks_after_operation, timeout=timeout)
                        convert_to_robot_kw(self.run_postconditions)
                    except (AdminApiProcedureFailureException, AdminApiNoResponseException,
                            AdminApiProcedureTimeoutException, WebSocketConnectionClosedException):
                        convert_to_robot_kw(log_warn_to_console,
                                            msg="ADMIN EXCEPTION CATCH DURING OPERATION EXECUTION: \n {}"
                                            .format(traceback.format_exc()), log_hierarchy=3)
                        convert_to_robot_kw(self.actions_when_bts_did_not_go_on_air, timeout=timeout)
                        convert_to_robot_kw(self._fail_iteration)
                    except Exception:
                        logging.error("Unexpected error occurred during operation: {}".format(traceback.format_exc()))
                        convert_to_robot_kw(self._fail_iteration)
                    finally:
                        convert_to_robot_kw(self.set_iteration_status)
                        convert_to_robot_kw(self.collect_logs_after_run)
        except Exception as ex:
            logging.error("Unexpected error occurred during execution: {}".format(traceback.format_exc()))
            raise ex
        finally:
            with RobotWrapper(wrap_name="TEARDOWN", wrap_type="teardown"):
                self.actions_after_loop()
                self.teardown_connections()
                if self._any_iteration_failed:
                    BuiltIn().run_keyword('FAIL', 'At least one of iteration FAILED - Please check the logs')
                return self._all_results

    def actions_before_loop(self):
        if self.verify_params:
            self.custom_logger(log_info_to_console, msg="Checking mandratory configuration")
            convert_to_robot_kw(common_verify_mandatory_configuration, bts_id=self.bts_id, du_id=self.du_id)
            if convert_to_robot_kw(self.wait_for_all_cells_onair, timeout=23 * 60) is False:
                raise Exception("BTS not onair after param change!")
        self._rfc_cells = convert_to_robot_kw(self.asir.get_rfc_cells, bts_id=self.bts_id) if self.asir else []
        convert_to_robot_kw(function=self.delete_old_alarm_watchdog_process)
        bts_version = convert_to_robot_kw(function=self.bbu.get_bts_sw_version, bts_id=self.bts_id, du_id=self.du_id)
        self.custom_logger(log_info_to_console, msg="Active sw BTS version: {}".format(bts_version))
        self._all_results["bts_build"] = bts_version
        convert_to_robot_kw(self.check_partition_available_space, log_info=True)
        self._cells_number = convert_to_robot_kw(self.cell.get_number_of_cells, bts_id=self.bts_id, du_id=self.du_id,
                                                 skip_nb_iot=False)
        convert_to_robot_kw(self.prepare_watchdog, bts_build=bts_version)
        convert_to_robot_kw(self.watchdog.watch_alarms, log_dir=self._watchdog_logs_dir,
                            bts_config=self.bbu.get_bts_config(bts_id=self.bts_id), reconnect=True)

    def run_preconditions(self, iteration):
        self._current_status = None
        self._iteration_number = iteration
        self._iteration_log_path = os.path.join(self._robot_log_path, 'Iteration_{}'.format(self._iteration_number))
        self._iteration_start_time = datetime.datetime.now()
        self._iteration_status[iteration] = {}
        convert_to_robot_kw(self._start_collecting_logs)

    def checks_before_operation(self, **kwargs):
        convert_to_robot_kw(self.check_partition_available_space, log_info=False)

    def actions_before_operation(self, **kwargs):
        pass

    def run_operation(self, **kwargs):
        pass

    def actions_after_operation(self, **kwargs):
        convert_to_robot_kw(self.bbu.disconnect, bts_id=self.bts_id, du_id=self.du_id)

    def checks_after_operation(self, timeout, **kwargs):
        if convert_to_robot_kw(self.wait_for_all_cells_onair, timeout=timeout) is False:
            convert_to_robot_kw(self.actions_when_bts_did_not_go_on_air, timeout=timeout)

    def run_postconditions(self):
        convert_to_robot_kw(self._verify_alarms)
        if self.asir is not None:
            convert_to_robot_kw(self._verify_rfc_cells_status)
            convert_to_robot_kw(self._get_asir_webem_alarms)
        if self._current_status != "FAILED":
            self._current_status = "PASSED"
        if self._iteration_number % self.alarm_watchdog_restart == 0 and self._iteration_number != 0:
            convert_to_robot_kw(self._reset_alarm_watchdog)
            convert_to_robot_kw(self._log_failed_iterations)

    def actions_after_loop(self):
        BuiltIn().log(self._iteration_status)
        with open(os.path.join(self._robot_log_path,
                               '{}_iteration_results.json'.format(ws_du.format(self.bts_type, self.bts_id,
                                                                               self.du_id))), 'w') as f:
            f.write(json.dumps(self._iteration_status, indent=4, sort_keys=True).replace("\\n", "\n"))
        self.watchdog.stop_watching_alarms()
        if self.delete_watchdog_alarms is True:
            shutil.rmtree(self._watchdog_logs_dir)

    def teardown_connections(self):
        self.bbu._teardown_all_aliases()
        if self.asir is not None:
            try:
                self.asir.disconnect(bts_id=self.bts_id)
            except ProtocolError as e:
                self.custom_logger(log_warn_to_console, msg=f"Cannot close ASIR connection: {e}",
                                   log_hierarchy=3)

    def set_iteration_status(self):
        if self._current_status == 'PASSED':
            self._iteration_status[self._iteration_number]["status"] = "PASSED"
        else:
            self._iteration_status[self._iteration_number]["status"] = "FAILED"

    def collect_logs_after_run(self):
        if self._iteration_status[self._iteration_number]["status"] == "FAILED":
            self._any_iteration_failed = True
            convert_to_robot_kw(function=self.collect_logs_after_fail)
        elif self.collect_passed_snapshot is True and self._first_passed_iteration is None:
            self.custom_logger(log_info_to_console, msg="It is first PASSED iteration - Collect Snapshot",
                               log_hierarchy=2)
            convert_to_robot_kw(self.collect_snapshot)
            self._first_passed_iteration = self._iteration_number
        convert_to_robot_kw(self._stop_collecting_logs)
        if self._iteration_status[self._iteration_number]["status"] == 'PASSED':
            convert_to_robot_kw(self._delete_logs_if_iteration_passed)

    def _fail_iteration(self):
        self._current_status = 'FAILED'

    def custom_logger(self, logger_func, *args, **kwargs):
        convert_to_robot_kw(logger_func, *args, **kwargs)

    def _delay_for_checking(self):
        if self.delay_for_checking_onAir:
            self.custom_logger(log_info_to_console,
                               msg="Waiting {} seconds".format(self.delay_for_checking_onAir), log_hierarchy=2)
            self._sleep(self.delay_for_checking_onAir)

    def _wait_until_cells_on_air(self, timeout):
        start_time = time.time()
        try:
            convert_to_robot_kw(function=self.cell.wait_for_all_cells_to_be_onair, bts_id=self.bts_id,
                                du_id=self.du_id, timeout=timeout, expected_cell_amount=self._cells_number)
            self.custom_logger(log_info_to_console, msg="All cells are UP", log_hierarchy=3)
            return True
        except (AdminApiProcedureFailureException, AdminApiNoResponseException, AdminApiProcedureTimeoutException,
                WebSocketConnectionClosedException) as ex:
            logging.debug("Admin exception when checking on-air {}".format(ex))
            time.sleep(23)
            new_timeout = timeout - (time.time() - start_time)
            if new_timeout > 0:
                return convert_to_robot_kw(self._wait_until_cells_on_air, timeout=new_timeout)
            self.custom_logger(log_warn_to_console, msg="All cels are not UP, there was AdminException",
                               log_hierarchy=3)
            return False
        except CellNotOnAir:
            self.custom_logger(log_warn_to_console, msg="All cels are not UP after timeout: {}".format(timeout),
                               log_hierarchy=3)
            return False

    def _recover_bts(self, timeout):
        self.custom_logger(log_warn_to_console, msg="Recover BTS", log_hierarchy=3)
        logging.debug("Dump current BTS status")
        convert_to_robot_kw(function=self.bbu.get_bts_info, bts_id=self.bts_id, du_id=self.du_id)
        convert_to_robot_kw(self.collect_logs_after_fail)
        convert_to_robot_kw(self._verify_alarms)
        self.custom_logger(log_warn_to_console, msg="Reset BTS as recovery", log_hierarchy=4)
        convert_to_robot_kw(function=self.bbu.reset_bts, bts_id=self.bts_id, du_id=self.du_id)
        convert_to_robot_kw(function=self.bbu.disconnect, bts_id=self.bts_id, du_id=self.du_id)
        convert_to_robot_kw(self._delay_for_checking)
        result = convert_to_robot_kw(function=self.wait_for_all_cells_onair, timeout=timeout, log_hierarchy=4)
        if result is False and self.perform_ru_power_reset_after_fail is True:
            log_warn_to_console("Site not on-air after BTS reset, run all RU power reset as recovery",
                                log_hierarchy=3)
            convert_to_robot_kw(function=self.ru.power_reset_radio_unit, bts_id=self.bts_id, du_id=self.du_id)
            result = convert_to_robot_kw(function=self.wait_for_all_cells_onair, timeout=timeout, log_hierarchy=4)
        return result

    def actions_when_bts_did_not_go_on_air(self, timeout):
        wait_to_23_minutes = 23 * 60 - int(timeout) if timeout < 1380 else int(timeout * 0.23)
        self.custom_logger(log_info_to_console, msg="Waiting and checking on-air for {} sec to automatic BTS recovery".
                           format(wait_to_23_minutes), log_hierarchy=3)
        if convert_to_robot_kw(function=self.wait_for_all_cells_onair,
                               timeout=wait_to_23_minutes + self.delay_for_checking_onAir, log_hierarchy=3) \
                is False:
            with RobotWrapper(wrap_name="BTS RECOVERY LOOP, ITERATIONS: {}".format(self._recover_reset_amount + 1),
                              wrap_type="for") as wrapper:
                for attempt in range(1, self._recover_reset_amount + 1):
                    wrapper.create_level("RECOVERY ATTEMPT = {}".format(attempt), wrap_type="foritem", level=2)
                    result = convert_to_robot_kw(function=self._recover_bts, timeout=timeout)
                    if result is True:
                        self.custom_logger(log_info_to_console, msg="Site recovered", log_hierarchy=3)
                        break
                    self.custom_logger(log_info_to_console,
                                       msg="Sleep for 23 min, before next try to recover bts", log_hierarchy=3)
                    convert_to_robot_kw(self._sleep, sleep_time=23 * 60)
                else:
                    convert_to_robot_kw(self.collect_logs_after_fail)
                    convert_to_robot_kw(self._verify_alarms)
                    convert_to_robot_kw(self._stop_collecting_logs)
                    self.custom_logger(log_warn_to_console,
                                       msg="SITE WERE UNABLE TO RECOVER AFTER {} TRIES, SLEEP FOR 72H".
                                       format(self._recover_reset_amount), log_hierarchy=4)
                    convert_to_robot_kw(self._sleep, sleep_time=60 * 60 * 72)
        convert_to_robot_kw(function=self._fail_iteration)

    def wait_for_all_cells_onair(self, timeout=600, log_hierarchy=2):
        timeout = timeout - self.delay_for_checking_onAir
        self.custom_logger(log_info_to_console, msg="Waiting {} seconds for all cell on Air".
                           format(timeout), log_hierarchy=log_hierarchy)
        return convert_to_robot_kw(self._wait_until_cells_on_air, timeout=timeout)

    @load_moler_configuration_from_tl()
    def _check_if_enough_space_for_iteration(self, free_space):
        outputdir = get_builtin_value('OUTPUT_DIR')
        device = convert_to_robot_kw(DeviceFactory.get_device, name=ws_du.format(self.bts_type, self.bts_id,
                                                                                 self.du_id))
        files = convert_to_robot_kw(device.get_cmd, cmd_name='ls', cmd_params={"path": outputdir, "options": "-l"})()
        output_size = int(files["files"]["output.xml"]["size_bytes"] / 1000000)
        convert_to_robot_kw(device.get_cmd, cmd_name='cd', cmd_params={"path": "'{}'".format(self._robot_log_path)})()
        files = convert_to_robot_kw(device.get_cmd, cmd_name='du', cmd_params={"options": "-sh *"})()
        max_iteartion_size = int(max([files[file]["size_bytes"] for file in files]) / 1000000)
        if int(free_space) < max(output_size * 2, max_iteartion_size):
            return False
        return True

    @load_moler_configuration_from_tl()
    def check_partition_available_space(self, partition="/home", log_info=True):
        device = convert_to_robot_kw(function=DeviceFactory.get_device, name=ws_du.format(self.bts_type, self.bts_id,
                                                                                          self.du_id))
        partition_space = convert_to_robot_kw(function=device.get_cmd, cmd_name="df")()
        partition_space = partition_space["by_MOUNTPOINT"][partition]["Avail"]
        free_space = round(float(int(partition_space) / 1000))
        if int(partition_space) < self.required_space:
            self.custom_logger(log_warn_to_console, msg="LOW AVAILABLE PARTITION {} SPACE, ONLY {} GB LEFT".
                               format(partition, free_space), log_hierarchy=3)
            if self.graceful_shutdown is True and convert_to_robot_kw(self._check_if_enough_space_for_iteration,
                                                                      free_space=partition_space) is False:
                BuiltIn().fatal_error("TOO LOW SPACE, PERFORMING GRACEFUL SHUTDOWN")
        elif log_info is True:
            self.custom_logger(log_info_to_console, msg="Available space on {} is: {} GB".
                               format(partition, free_space), log_hierarchy=3)

    @staticmethod
    def _sleep(sleep_time):
        try:
            time.sleep(sleep_time)
        except Exception:
            BuiltIn().fatal_error("SLEEP INTERRUPTED")

    @staticmethod
    def set_robot_listener(listener_path='taf.rfrl.procedures.resources.python.OAM_KPI.KPIListener', *args):
        if listener_path not in list(BuiltIn().get_library_instance(all=True)):
            BuiltIn().import_library(listener_path, get_builtin_value('OUTPUT_DIR'), *args)

    def _log_failed_iterations(self):
        try:
            message = "  ".join([str(it_num) for it_num in range(1, self._iteration_number)
                                 if self._iteration_status[it_num]["status"] == "FAILED"])
            if len(message) != 0:
                self.custom_logger(log_warn_to_console, msg="Numbers of failed iterations: " + message,
                                   log_hierarchy=4)
        except Exception:
            pass

    def _start_collecting_logs(self):
        self.custom_logger(log_info_to_console, msg="Start collecting btslog", log_hierarchy=2)
        convert_to_robot_kw(function=self.log.start_collecting_btslog, bts_id=self.bts_id, du_id=self.du_id)
        self.custom_logger(log_info_to_console, msg="Start collecting RU console log if LMI configured", log_hierarchy=2)
        convert_to_robot_kw(function=self.gnb_ru_lmi.setup_serial_console_connection_for_all_rus, bts_id=self.bts_id,
                            du_id=self.du_id)

    def _stop_collecting_logs(self):
        self.custom_logger(log_info_to_console, msg="Stop collecting btslog", log_hierarchy=2)
        convert_to_robot_kw(function=self.log.stop_collecting_btslog, bts_id=self.bts_id, du_id=self.du_id,
                            log_dir=self._iteration_log_path,
                            file_prefix=ssh_bts_du.format(self.bts_type, self.bts_id, self.du_id,
                                                          self._iteration_number))
        self.custom_logger(log_info_to_console, msg="Stop collecting RU console log if LMI configured", log_hierarchy=2)
        convert_to_robot_kw(function=self.gnb_ru_lmi.collect_console_log_from_all_setup_rus,
                            log_dir=self._iteration_log_path)
        convert_to_robot_kw(function=self.gnb_ru_lmi.teardown_serial_console_connection_for_all_setup_rus)

    def collect_snapshot(self, counter=1):
        try:
            snapshot_location = convert_to_robot_kw(function=self.log.collect_snapshot, bts_id=self.bts_id,
                                                    du_id=self.du_id, log_dir=self._iteration_log_path, timeout=2400)
            logging.debug("Snapshot location: {}".format(snapshot_location))
        except Exception:
            if counter == 3:
                self.custom_logger(log_warn_to_console, msg="FAILED TO COLLECT SNAPSHOT", log_hierarchy=3)
                return
            self.custom_logger(log_warn_to_console,
                               msg="Failed to collect snapshot due to {}, sleep 600 sec and "
                                   "reload admin and try to collect again".format(traceback.format_exc()),
                               log_hierarchy=3)
            convert_to_robot_kw(self.bbu.disconnect, bts_id=self.bts_id, du_id=self.du_id)
            convert_to_robot_kw(self._sleep, sleep_time=600)
            convert_to_robot_kw(self.bbu.connect, bts_id=self.bts_id, du_id=self.du_id)
            convert_to_robot_kw(self.collect_snapshot, counter=counter + 1)

    def collect_logs_after_fail(self):
        self.custom_logger(log_warn_to_console, msg="Iteration failed - Collect snapshot", log_hierarchy=2)
        convert_to_robot_kw(self.collect_snapshot)
        if self.collect_ru_logs is True:
            self.custom_logger(log_info_to_console, msg="RUs snapshot collection started", log_hierarchy=2)
            try:
                convert_to_robot_kw(self.get_rus_snapshot)
            except Exception:
                self.custom_logger(log_warn_to_console, msg="Failed to collect RU logs", log_hierarchy=3)
                self.custom_logger(log_info_to_console, msg=traceback.format_exc(), log_hierarchy=3)
        self.custom_logger(log_info_to_console, msg="Logs location: {}".format(self._iteration_log_path),
                           log_hierarchy=3)

    @load_moler_configuration_from_tl()
    def get_rus_snapshot(self):
        operations = []
        ru_devs = [device for ru_regex in self.ru_device_regex
                   for device in convert_to_robot_kw(get_devices_from_regex, pattern=ru_regex)]
        with RobotWrapper(wrap_name="RU SNAPSHOT LOOP, DEVICES: {}".format(str(ru_devs)), wrap_type="for") as wrapper:
            for ru_dev in list(ru_devs):
                wrapper.create_level("DEVICE = {}".format(ru_dev), wrap_type="foritem", level=2)
                try:
                    device = convert_to_robot_kw(DeviceFactory.get_device, name=ru_dev, initial_state="RU")
                    logs_name = "{}_logs_{}.zip".format(ru_dev, device.ru_ip_address.replace(".", "_"))
                    convert_to_robot_kw(device.goto_state, state="RU", rerun=7)
                    convert_to_robot_kw(device.get_cmd, cmd_name="telnet",
                                        cmd_params={"expected_prompt": r'AaShell>', "host": "0", "port": "15007",
                                                    "allowed_newline_after_prompt": True}, check_state=False)()
                    convert_to_robot_kw(device.get_cmd, cmd_name='run_script',
                                        cmd_params={"script_command": "log -a -z {}".format(logs_name),
                                                    "prompt": r'AaShell>',
                                                    "error_regex": "no error regex"})(timeout=90)
                    cmd = convert_to_robot_kw(device.get_cmd, cmd_name='run_script',
                                              cmd_params={"script_command": "quit", "error_regex": "no error regex"})
                    cmd.start(timeout=90)
                    operations.append(cmd)
                except DeviceChangeStateFailure as e:
                    convert_to_robot_kw(log_warn_to_console, msg="Failed to connect to RU: {}; {},"
                                        .format(ru_dev, e))
                except Exception as e:
                    convert_to_robot_kw(log_warn_to_console, msg="Failed:{},to collect logs from RU: {}"
                                        .format(e, ru_dev))
        for operation in operations:
            operation.await_done(timeout=90)
        self.custom_logger(log_info_to_console, msg="Getting RUs snapshot done", log_hierarchy=3)
        convert_to_robot_kw(self.collect_rus_snapshot, ru_devs=ru_devs)

    def collect_rus_snapshot(self, ru_devs):
        device = convert_to_robot_kw(DeviceFactory.get_device, name='UnixLocal')
        local_time = time.localtime()
        logs_path = os.path.join(self._iteration_log_path, "RU_SNAPs_{}_{}_{}".format(local_time.tm_hour,
                                                                                      local_time.tm_min,
                                                                                      local_time.tm_sec))
        convert_to_robot_kw(device.get_cmd, cmd_name='mkdir', cmd_params={"path": "'{}'".format(logs_path),
                                                                          "options": "-p"})()
        with RobotWrapper(wrap_name="RU SNAPSHOT COLLECT TO LOCAL LOOP, DEVICES: {}".format(str(ru_devs)),
                          wrap_type="for") as wrapper:
            for ru_dev in ru_devs:
                wrapper.create_level("DEVICE = {}".format(ru_dev), wrap_type="foritem", level=2)
                device = convert_to_robot_kw(DeviceFactory.get_device, name=ru_dev, initial_state="RU")
                ru_ip = device.ru_ip_address
                logs_name = "{}_logs_{}.zip".format(ru_dev, ru_ip.replace(".", "_"))
                find_results = convert_to_robot_kw(device.get_cmd, cmd_name='find',
                                                   cmd_params={"paths": ["/"],
                                                               "operators": "-iname '{}' 2>/dev/null".format(logs_name)}
                                                   )(timeout=120)
                for result in find_results["RESULT"]:
                    if logs_name in result:
                        ru_logs_path = result.split(logs_name)[0]
                        break
                else:
                    convert_to_robot_kw(log_info_to_console, msg="Cannot find logs {}".format(logs_name))
                    continue
                convert_to_robot_kw(download_files, local_dir=logs_path, device_name=ru_dev, remote_file=logs_name,
                                    remote_dir=ru_logs_path, from_state="RU", timeout=180)
        self.custom_logger(log_info_to_console, msg="RUs snapshots collected", log_hierarchy=3)

    @staticmethod
    def __delete_ims_if_run_passed(iteration_start_time, log_dir=None):
        """
        Delete ims2 logs if creation time is bigger than iteration start time
        :param iteration_start_time: datetime() object, time when iteration started
        :return: None
        """
        if log_dir is None:
            log_dir = get_builtin_value('OUTPUT_DIR')
        dir_files = os.listdir(log_dir)
        ims2_files_pattern = re.compile(r'.*ims2')
        for dir_file in dir_files:
            if ims2_files_pattern.match(dir_file):
                path_to_file = os.path.join(log_dir, dir_file)
                creation_time = os.stat(path_to_file).st_ctime
                iter_start_time_timestamp = time.mktime(iteration_start_time.timetuple())
                if creation_time > iter_start_time_timestamp:
                    os.remove(path_to_file)
                    logging.debug("Removed ims file: {}".format(path_to_file))

    def _delete_logs_if_iteration_passed(self):
        try:
            convert_to_robot_kw(function=self.__delete_ims_if_run_passed,
                                iteration_start_time=self._iteration_start_time)
            convert_to_robot_kw(function=self.__delete_ims_if_run_passed,
                                iteration_start_time=self._iteration_start_time,
                                log_dir=os.path.join(self._robot_log_path, 'alarms_watchdog'))
        except FileNotFoundError as e:
            logging.debug("Unable to delete IMS file: {}".format(e))

    @staticmethod
    def get_logs_path():
        set_test_case_log_path()
        return get_log_path()

    def prepare_watchdog(self, bts_build):
        if self._add_default_faults:
            for alarm in get_default_allowed_alarms(bts_build):
                alarm_params = convert_to_robot_kw(function=self.alarm._get_alarm_params, alarm=alarm)
                convert_to_robot_kw(self.watchdog.allow_alarm, **alarm_params)
        for alarm in self.additional_allowed_alarms:
            alarm_params = convert_to_robot_kw(function=self.alarm._get_alarm_params, alarm=alarm)
            convert_to_robot_kw(self.watchdog.allow_alarm, **alarm_params)

    def _reset_alarm_watchdog(self):
        self.custom_logger(log_info_to_console, msg="Performing alarm_watchdog reset", log_hierarchy=1)
        convert_to_robot_kw(self.watchdog.stop_watching_alarms)
        if self.delete_watchdog_alarms is True:
            shutil.rmtree(self._watchdog_logs_dir)
        bts_version = convert_to_robot_kw(function=self.bbu.get_bts_sw_version, bts_id=self.bts_id, du_id=self.du_id)
        convert_to_robot_kw(self.prepare_watchdog, bts_build=bts_version)
        convert_to_robot_kw(self.watchdog.watch_alarms, log_dir=self._watchdog_logs_dir,
                            bts_config=self.bbu.get_bts_config(bts_id=self.bts_id), reconnect=True)

    def _verify_alarms(self):
        convert_to_robot_kw(self.check_if_critical_alarms_exists_on_the_end_of_iteration)
        convert_to_robot_kw(self.verify_alarms_at_the_end_of_iteration)
        convert_to_robot_kw(self.verify_if_any_unexpected_alarm_occurred_during_iteration)

    def check_if_critical_alarms_exists_on_the_end_of_iteration(self):
        try:
            convert_to_robot_kw(function=self.alarm.verify_alarms_are_not_active,
                                alarms_to_be_verified=self.temp_critical_alarms, du_id=self.du_id, bts_id=self.bts_id)
        except UnallowedAlarms as e:
            convert_to_robot_kw(function=self.collect_logs_after_fail)
            convert_to_robot_kw(function=self._stop_collecting_logs)
            self.custom_logger(log_warn_to_console,
                               msg=" CRITICAL ALARMS {} APPEARED, EXECUTION IS SLEPT FOR 72H".format(str(e)))
            convert_to_robot_kw(self._sleep, sleep_time=60 * 60 * 72)

    def verify_alarms_at_the_end_of_iteration(self, wait_delay=True):
        self.custom_logger(log_info_to_console, msg="Check active alarms", log_hierarchy=2)
        try:
            convert_to_robot_kw(function=self.alarm.verify_alarms_are_not_active,
                                alarms_to_be_verified=self.temp_allowed_alarms, du_id=self.du_id, bts_id=self.bts_id)
            with RobotWrapper(wrap_name="VERIFY ALARMS LOOP", wrap_type="for") as wrapper:
                logging.debug("Detected alarms:\n {}".format(str(self.watchdog._detected_alarms)))
                for detected_alarm in list(self.watchdog._detected_alarms):
                    wrapper.create_level("CHECKED ALARM = {}".format(detected_alarm), wrap_type="foritem", level=2)
                    if convert_to_robot_kw(function=self._check_if_alarm_in_alarm_list, detected_alarm=detected_alarm,
                                           alarm_list=self.temp_allowed_alarms) is True:
                        self.watchdog._detected_alarms.remove(detected_alarm)
                    if convert_to_robot_kw(function=self._check_if_alarm_in_alarm_list, detected_alarm=detected_alarm,
                                           alarm_list=self.critical_alarms) is True:
                        convert_to_robot_kw(function=self.collect_logs_after_fail)
                        convert_to_robot_kw(function=self._stop_collecting_logs)
                        self.custom_logger(log_warn_to_console,
                                           msg=" CRITICAL ALARM {} APPEARED, EXECUTION IS SLEPT FOR 72H"
                                           .format(str(detected_alarm)))
                        convert_to_robot_kw(self._sleep, sleep_time=60 * 60 * 72)
            self.custom_logger(log_info_to_console, msg="No additional alarms are visible - OK",
                               log_hierarchy=3)
        except UnallowedAlarms as e:
            if wait_delay and self.delay_for_checking_allowed_alarms:
                logging.info("Waiting {} seconds till alarms disappear".format(self.delay_for_checking_allowed_alarms))
                time.sleep(self.delay_for_checking_allowed_alarms)
                convert_to_robot_kw(function=self.verify_alarms_at_the_end_of_iteration, wait_delay=False)
                return
            self._iteration_status[self._iteration_number]["unallowed_alarms_after_test"] = str(e)
            self.custom_logger(log_warn_to_console, msg="Unallowed Alarms visible after test: {}"
                               .format(str(e)), log_hierarchy=3)
            self.custom_logger(log_warn_to_console, msg="Failing iteration number {}"
                               .format(self._iteration_number), log_hierarchy=2)
            self._current_status = 'FAILED'

    @staticmethod
    def _check_if_alarm_in_alarm_list(detected_alarm, alarm_list):
        match = []
        for alarm in alarm_list:
            allowed_alarm = alarm if isinstance(alarm, dict) else {"fault_id": alarm}
            match.append(all([str(getattr(detected_alarm, attr)) == str(allowed_alarm[attr])
                              for attr in list(allowed_alarm)]))
        return any(match)

    def verify_if_any_unexpected_alarm_occurred_during_iteration(self):
        try:
            convert_to_robot_kw(function=self.watchdog.check_detected_alarms)
        except DisallowedAlarmsDetected as e:
            self.custom_logger(log_warn_to_console,
                               msg="Unexpected alarms were visible during iteration {}".format(str(e)), log_hierarchy=3)
            self.custom_logger(log_warn_to_console, msg="Failing iteration number {}".
                               format(self._iteration_number), log_hierarchy=2)
            self._iteration_status[self._iteration_number]["unallowed_alarms_during_test"] = str(e)
            self._current_status = 'FAILED'
        self.watchdog._detected_alarms = []
        self.watchdog._lost_alarms = []

    @load_moler_configuration_from_tl()
    def delete_old_alarm_watchdog_process(self):
        try:
            for key, value in BuiltIn().get_library_instance(all=True).items():
                if "taf.rfrl.bts.devices.du.alarm_verification.GnbAlarmVerification" in str(key) or \
                        "taf.rfrl.bts.devices.du.alarm_verification.GnbAlarmVerification" in str(value):
                    if value.alarms_watcher:
                        watchers_started = [value.alarms_watcher[watcher_alias]._keep_watching
                                            for watcher_alias in value.alarms_watcher]
                        if any(watchers_started):
                            log_warn_to_console("OTHER ALARMS WATCHDOG DETECTED, PLEASE NOTE, "
                                                "THAT YOUR ALLOWED ALARMS TO THIS TEST ARE:\n {} \n"
                                                "PLEASE DO NOT START OTHER WATCHDOG AND PROVIDE "
                                                "YOUR ALLOWED ALARMS TO PARAMETER additional_allowed_alarms"
                                                .format(self.additional_allowed_alarms),
                                                log_hierarchy=3)
        except Exception:
            pass
        device = convert_to_robot_kw(function=DeviceFactory.get_device, name=ws_du.format(self.bts_type, self.bts_id,
                                                                                          self.du_id))
        convert_to_robot_kw(function=device.get_cmd, cmd_name='pkill', cmd_params={"name": "-f alarms_watchdog"})()
